import { test } from "node:test";
import assert from "node:assert/strict";
import { setTimeout as sleep } from "node:timers/promises";
import { ShardRouter, hashKey } from "../src/shards/router.ts";
import { ShardedUserStore } from "../src/shards/userStore.ts";
import { batchMoves, planMigration } from "../src/shards/migration.ts";
import { scatterGather } from "../src/shards/scatterGather.ts";

const ids = Array.from({ length: 5000 }, (_, i) => `user-${i}`);

test("short keys route as before", () => {
    const router = new ShardRouter(["a", "b", "c", "d"]);
    assert.equal(hashKey("u1"), 3676);
    assert.equal(router.indexFor("u1"), 0);
});

test("every key routes to an existing shard", () => {
    const router = new ShardRouter(["a", "b", "c", "d"]);
    const bad = ids.filter((id) => {
        const i = router.indexFor(id);
        return !(Number.isInteger(i) && i >= 0 && i < 4);
    });
    console.log(`${bad.length} of ${ids.length} keys routed outside 0..3, e.g.`, bad.slice(0, 3).map((id) => `${id} -> ${router.indexFor(id)}`));
    assert.equal(bad.length, 0);
});

test("routing is stable and roughly even", () => {
    const router = new ShardRouter([0, 1, 2, 3]);
    const counts = [0, 0, 0, 0];
    for (const id of ids) {
        assert.equal(router.indexFor(id), router.indexFor(id));
        counts[router.indexFor(id)]++;
    }
    for (const c of counts) assert.ok(c > 1000 && c < 1500, `shard sizes ${counts}`);
});

test("users can be stored and read back on any shard", async () => {
    const store = new ShardedUserStore(4);
    for (const id of ids.slice(0, 500)) await store.put({ id, email: `${id}@example.com`, name: id });
    for (const id of ids.slice(0, 500)) assert.equal((await store.get(id))?.id, id);
    assert.equal((await store.findByEmail("user-321@example.com"))?.id, "user-321");
    assert.equal(store.sizes().reduce((a, b) => a + b, 0), 500);
});

test("a 4 -> 5 shard migration moves only keys whose shard changes, to real shards", () => {
    const plan = planMigration(ids, 4, 5);
    assert.equal(plan.moves.length + plan.staying, ids.length);
    assert.ok(plan.moves.every((m) => m.to >= 0 && m.to < 5 && m.from >= 0 && m.from < 4), "every move has valid shards");
    assert.equal(plan.incomingByShard.reduce((a, b) => a + b, 0), plan.moves.length);
    // modulo placement: a key stays only if hash % 4 === hash % 5, about 1 in 5
    assert.ok(plan.staying > 700 && plan.staying < 1300, `staying ${plan.staying}`);
});

test("moves are batched per source and target shard", () => {
    const moves = [
        { key: "a", from: 0, to: 4 }, { key: "b", from: 0, to: 4 }, { key: "c", from: 0, to: 4 },
        { key: "d", from: 1, to: 4 }, { key: "e", from: 0, to: 2 },
    ];
    assert.deepEqual(batchMoves(moves, 2).map((b) => b.map((m) => m.key)), [["a", "b"], ["c"], ["d"], ["e"]]);
});

test("scatter-gather returns partial results and names the slow shard", async () => {
    const shards = [{ name: "users-0", delay: 1 }, { name: "users-1", delay: 200 }, { name: "users-2", delay: 1 }];
    const gathered = await scatterGather(shards, async (s) => (await sleep(s.delay), s.name.length), 50);
    assert.deepEqual(gathered, { results: [7, 7], failedShards: ["users-1"] });
});
